  "metadata": "{\"compiler\":{\"version\":\"0.8.24+commit.e11b9ed9\"},\"language\":\"Solidity\",\"output\":{\"abi\":[{\"inputs\":[{\"internalType\":\"address[]\",\"name\":\"singletons\",\"type\":\"address[]\"},{\"internalType\":\"bytes32[]\",\"name\":\"proxyCodehashes\",\"type\":\"bytes32[]\"}],\"stateMutability\":\"nonpayable\",\"type\":\"constructor\"},{\"inputs\":[{\"internalType\":\"address\",\"name\":\"safe\",\"type\":\"address\"},{\"internalType\":\"address\",\"name\":\"recordsModule\",\"type\":\"address\"}],\"name\":\"isAuthor\",\"outputs\":[{\"internalType\":\"bool\",\"name\":\"\",\"type\":\"bool\"}],\"stateMutability\":\"view\",\"type\":\"function\"}],\"devdoc\":{\"kind\":\"dev\",\"methods\":{\"constructor\":{\"params\":{\"proxyCodehashes\":\"The keccak256 of Safe's proxy runtime code as        deployed on this chain. Compare with `keccak256(eth_getCode(proxy))`        for a Safe you trust, and re-verify after any Safe release.\",\"singletons\":\"The Safe singleton implementations this chain's proxies        may point at.\"}}},\"title\":\"S2SAuthorGate\",\"version\":1},\"userdoc\":{\"kind\":\"user\",\"methods\":{\"isAuthor(address,address)\":{\"notice\":\"True only when `safe` is Safe's proxy code, proxies onto an         allowed singleton, has `recordsModule` enabled, and that module         answers `safe()` with `safe`.\"}},\"notice\":\"Answers whether an address is an author Safe holding `recordsModule`         as its records module.         Two allowlists are fixed at construction and there is no admin:         `singletons` (Safe singleton implementations) and `proxyCodehashes`         (the runtime code hash of Safe's proxy). Both must be verified         against the Safe deployments on the chain this gate is deployed to,         not guessed \\u2014 a gate with a wrong code hash rejects every real Safe,         and a gate with a wrong singleton accepts a proxy pointed at a fake         implementation.         The order matters. The code hash is the anchor: any contract can         answer `masterCopy()`, but only Safe's proxy has the proxy runtime         code. The proxy then answers `masterCopy()` from its own dispatcher,         so a fake singleton contract cannot lie about which singleton a         contract that passed the code-hash test is proxying onto. Only then         is the module read: it must be enabled on the Safe, and the module         must answer that *this* Safe is its own.         No try/catch. A contract that passed the code-hash test is Safe's         proxy and its `masterCopy()` cannot revert; if the module's `safe()`         reverts, the call reverts and the caller is not an authorised author.         A module with no code is rejected before the call, so an EOA passed         as `recordsModule` is `false`, not a revert from an empty call.\",\"version\":1}},\"settings\":{\"compilationTarget\":{\"project/src/S2SAuthorGate.sol\":\"S2SAuthorGate\"},\"evmVersion\":\"shanghai\",\"libraries\":{},\"metadata\":{\"bytecodeHash\":\"ipfs\",\"useLiteralContent\":true},\"optimizer\":{\"enabled\":true,\"runs\":200},\"remappings\":[],\"viaIR\":true},\"sources\":{\"project/src/S2SAuthorGate.sol\":{\"content\":\"// SPDX-License-Identifier: MIT\\npragma solidity ^0.8.19;\\n\\n/// @notice The question `S2SRegistry` asks before it accepts a registration.\\ninterface IAuthorGate {\\n    function isAuthor(address safe, address recordsModule) external view returns (bool);\\n}\\n\\n/// @dev The two declarations a Safe proxy answers from its own code.\\ninterface ISafeProxy {\\n    function masterCopy() external view returns (address);\\n}\\n\\ninterface ISafeModuleManager {\\n    function isModuleEnabled(address module) external view returns (bool);\\n}\\n\\n/// @dev `S2SRecordsModuleV0_1` publishes `safe()`.\\ninterface IAuthorRecordsModule {\\n    function safe() external view returns (address);\\n}\\n\\n/**\\n * @title S2SAuthorGate\\n * @notice Answers whether an address is an author Safe holding `recordsModule`\\n *         as its records module.\\n *\\n *         Two allowlists are fixed at construction and there is no admin:\\n *         `singletons` (Safe singleton implementations) and `proxyCodehashes`\\n *         (the runtime code hash of Safe's proxy). Both must be verified\\n *         against the Safe deployments on the chain this gate is deployed to,\\n *         not guessed \\u2014 a gate with a wrong code hash rejects every real Safe,\\n *         and a gate with a wrong singleton accepts a proxy pointed at a fake\\n *         implementation.\\n *\\n *         The order matters. The code hash is the anchor: any contract can\\n *         answer `masterCopy()`, but only Safe's proxy has the proxy runtime\\n *         code. The proxy then answers `masterCopy()` from its own dispatcher,\\n *         so a fake singleton contract cannot lie about which singleton a\\n *         contract that passed the code-hash test is proxying onto. Only then\\n *         is the module read: it must be enabled on the Safe, and the module\\n *         must answer that *this* Safe is its own.\\n *\\n *         No try/catch. A contract that passed the code-hash test is Safe's\\n *         proxy and its `masterCopy()` cannot revert; if the module's `safe()`\\n *         reverts, the call reverts and the caller is not an authorised author.\\n *         A module with no code is rejected before the call, so an EOA passed\\n *         as `recordsModule` is `false`, not a revert from an empty call.\\n */\\ncontract S2SAuthorGate {\\n\\n    mapping(address => bool) private _singleton;\\n    mapping(bytes32 => bool) private _proxyCodehash;\\n\\n    /**\\n     * @param singletons The Safe singleton implementations this chain's proxies\\n     *        may point at.\\n     * @param proxyCodehashes The keccak256 of Safe's proxy runtime code as\\n     *        deployed on this chain. Compare with `keccak256(eth_getCode(proxy))`\\n     *        for a Safe you trust, and re-verify after any Safe release.\\n     */\\n    constructor(address[] memory singletons, bytes32[] memory proxyCodehashes) {\\n        for (uint256 i = 0; i < singletons.length; i++) {\\n            _singleton[singletons[i]] = true;\\n        }\\n        for (uint256 i = 0; i < proxyCodehashes.length; i++) {\\n            _proxyCodehash[proxyCodehashes[i]] = true;\\n        }\\n    }\\n\\n    /// @notice True only when `safe` is Safe's proxy code, proxies onto an\\n    ///         allowed singleton, has `recordsModule` enabled, and that module\\n    ///         answers `safe()` with `safe`.\\n    function isAuthor(address safe, address recordsModule) external view returns (bool) {\\n        if (safe.code.length == 0) return false;\\n        if (!_proxyCodehash[safe.codehash]) return false;\\n        if (!_singleton[ISafeProxy(safe).masterCopy()]) return false;\\n        if (recordsModule.code.length == 0) return false;\\n        if (!ISafeModuleManager(safe).isModuleEnabled(recordsModule)) return false;\\n        return IAuthorRecordsModule(recordsModule).safe() == safe;\\n    }\\n}\\n\",\"keccak256\":\"0x5d496ae6564b37cb444c63ff7af4b4575294db81eecad9d7d08149289fd0e520\",\"license\":\"MIT\"}},\"version\":1}",
